def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    me = [h[0] for h in history]
    op = [h[1] for h in history]
    op_c = op.count('C')
    op_d = n - op_c
    my_c = me.count('C')
    my_d = n - my_c
    last_op = op[-1]
    last_me = me[-1]
    remaining = 100 - n

    # detect pure/extreme defectors
    if op_d == n:
        return 'D'
    # detect pure cooperators: exploit heavily near end, cooperate otherwise
    if op_c == n:
        if remaining <= 3:
            return 'D'
        if n >= 20 and n % 5 == 0:
            return 'D'
        return 'C'

    # run length of opponent's last action
    run = 0
    for i in range(n - 1, -1, -1):
        if op[i] == last_op:
            run += 1
        else:
            break

    # Detect tit-for-tat mimicking: opponent's action correlates with our previous action
    mimic_hits = 0
    mimic_total = 0
    for i in range(1, n):
        mimic_total += 1
        if op[i] == me[i - 1]:
            mimic_hits += 1
    is_mimic = mimic_total >= 5 and mimic_hits >= mimic_total - 1

    # Detect grim trigger: opponent defected after our first defection and stayed D
    grim = False
    first_my_d = -1
    for i in range(n):
        if me[i] == 'D':
            first_my_d = i
            break
    if first_my_d >= 0:
        after = op[first_my_d:]
        if len(after) >= 2 and all(x == 'D' for x in after):
            grim = True

    # Endgame exploitation
    if remaining <= 1:
        return 'D'
    if remaining <= 3:
        # If opponent is very cooperative, defect
        if op_d * 5 <= n:
            return 'D'
        if last_op == 'D':
            return 'D'
        return 'C'
    if remaining <= 6:
        if op_d * 4 <= n:
            # mostly cooperative opponent: grab final payoffs
            return 'D'
        if last_op == 'D' and run >= 2:
            return 'D'
        return 'C'

    # Exploit mimic/TFT: cooperate to keep them cooperating, then defect a bit near end
    if is_mimic:
        if remaining <= 8:
            # alternate to squeeze value
            if last_me == 'C':
                return 'D'
            return 'C'
        return 'C'

    # Against grim trigger, never defect once we've cooperated: stay C
    if grim:
        # we already triggered it, so just defect back
        return 'D'

    # Against major defector
    if op_d * 2 >= n:
        if last_op == 'D' or run >= 2:
            return 'D'
        return 'D'

    # forgive single isolated defection if opponent generally cooperative
    if last_op == 'D':
        if run >= 3:
            return 'D'
        if op_d * 4 <= n:
            # generally cooperative; occasional defect - forgive (but punish once)
            if last_me == 'D':
                return 'C'
            return 'D'
        if run == 1 and op_c > op_d:
            return 'D' if rng.random() < 0.6 else 'C'
        return 'D'

    # Opponent cooperated
    if last_op == 'C':
        # If opponent is generally nice, mostly cooperate with rare probing
        if op_d * 5 <= n:
            if n > 25 and n % 11 == 0 and rng.random() < 0.4:
                return 'D'
            return 'C'
        # Mixed opponent: cooperate, tit-for-tat style
        return 'C'

    return 'C'
